//! Cross-implementation vectors were generated by PQ Mail/Bouncy Castle using
//! disposable software keys and example.test addresses. Only public data is
//! checked in. No test connects to PC/SC or invokes a private-key operation.
use anyhow::{bail, Result};
use base64::{engine::general_purpose::STANDARD,Engine};
use sequoia_pqmail_piv::restore::{restore,Card};
use serde_json::Value;
use sha2::{Digest,Sha256};
use std::collections::BTreeMap;

#[derive(Clone)]
struct Fake {serial:u32,keys:BTreeMap<u8,Vec<u8>>,objects:BTreeMap<u32,Vec<u8>>,fail:bool}
impl Card for Fake {
 fn serial(&mut self)->Result<u32>{Ok(self.serial)}
 fn public_key(&mut self,s:u8)->Result<Option<Vec<u8>>>{Ok(self.keys.get(&s).cloned())}
 fn object(&mut self,t:u32)->Result<Option<Vec<u8>>>{if self.fail {bail!("transport disconnected")};Ok(self.objects.get(&t).cloned())}
}
fn fixture()->(Fake,Value){
 let v:Value=serde_json::from_str(include_str!("data/restore-level3.json")).unwrap();
 let keys=v["keys"].as_object().unwrap().iter().map(|(s,k)|(u8::from_str_radix(s,16).unwrap(),STANDARD.decode(k.as_str().unwrap()).unwrap())).collect();
 (Fake{serial:123456,keys,objects:BTreeMap::new(),fail:false},v)
}
fn put(card:&mut Fake,tag:u32,generation:u64,bytes:&[u8]) {
 let mut manifest=b"PQMIDX01".to_vec();manifest.extend(generation.to_be_bytes());manifest.extend((bytes.len() as u32).to_be_bytes());manifest.extend(Sha256::digest(bytes));card.objects.insert(tag,manifest);
 for (i,data) in bytes.chunks(2048).enumerate(){let mut chunk=b"PQMCHK01".to_vec();chunk.extend(generation.to_be_bytes());chunk.extend((i as u32).to_be_bytes());chunk.extend(data);card.objects.insert(tag+1+i as u32,chunk);}
}
fn data(v:&Value,name:&str)->Vec<u8>{STANDARD.decode(v[name].as_str().unwrap()).unwrap()}
#[test]
fn bc_pure_and_composite_signatures_restore_ten_keys_and_three_certificates()->Result<()> {
 for name in ["pure","hybrid"] {
  let (mut card,v)=fixture();put(&mut card,0x5f5000,1,&data(&v,name));let before=card.clone();
  let restored=restore(&mut card,123456)?;
  assert_eq!(restored.certificate().fingerprint().to_hex(),v["fingerprint"].as_str().unwrap().to_uppercase());
  assert_eq!(restored.review()["publicKeySha256"].as_object().unwrap().len(),10);
  assert_eq!(restored.review()["trusted"],false);
  let parent=tempfile::tempdir()?;let out=parent.path().join("identity");restored.save(&out)?;
  for name in ["openpgp-v6.asc","openpgp-v4-hybrid.asc","openpgp-v4-classical.asc","identity.json"] {assert!(out.join(name).is_file());}
  assert!(restored.save(&out).is_err());
  assert_eq!(card.objects,before.objects);assert_eq!(card.keys,before.keys);
 }Ok(())
}
#[test]
fn bank_recovery_and_generation_selection()->Result<()> {
 let (mut card,v)=fixture();put(&mut card,0x5f5000,1,&data(&v,"pure"));put(&mut card,0x5f5100,2,&data(&v,"hybrid"));
 assert_eq!(restore(&mut card,123456)?.review()["generation"],2);
 card.objects.remove(&0x5f5102);let recovered=restore(&mut card,123456)?;
 assert_eq!(recovered.review()["generation"],1);assert!(!recovered.warnings.is_empty());
 Ok(())
}
#[test]
fn wrong_serial_every_key_and_transport_fail_closed() {
 let (mut card,v)=fixture();put(&mut card,0x5f5000,1,&data(&v,"hybrid"));
 assert!(restore(&mut card,123457).is_err());
 card.serial=123457;assert!(restore(&mut card,123457).is_err());card.serial=123456;
 for slot in card.keys.keys().copied().collect::<Vec<_>>() {let mut bad=card.clone();bad.keys.get_mut(&slot).unwrap()[20]^=1;assert!(restore(&mut bad,123456).is_err(),"slot {slot:02x}");}
 card.fail=true;assert!(format!("{}",restore(&mut card,123456).err().unwrap()).contains("transport"));
}
#[test]
fn compressed_boundaries_hash_and_unsupported_formats_fail() {
 let (card,v)=fixture();let original=data(&v,"hybrid");
 for change in 0..5 {
  let mut card=card.clone();let mut bytes=original.clone();
  match change {0=>bytes.push(0),1=>{bytes.pop();},2=>bytes[11]^=1,3=>bytes[0]^=1,_=>bytes[8..12].copy_from_slice(&u32::MAX.to_be_bytes())}
  put(&mut card,0x5f5000,1,&bytes);assert!(restore(&mut card,123456).is_err());
 }
 let mut card=card;put(&mut card,0x5f5000,1,&original);card.objects.get_mut(&0x5f5000).unwrap()[30]^=1;assert!(restore(&mut card,123456).is_err());
}
#[test]
fn signed_payload_and_both_signature_components_are_authenticated()->Result<()> {
 use std::io::{Read,Write};
 let (card,v)=fixture();let stored=data(&v,"hybrid");let mut decoded=Vec::new();flate2::read::ZlibDecoder::new(&stored[12..]).read_to_end(&mut decoded)?;
 let payload_len=u32::from_be_bytes(decoded[8..12].try_into()?) as usize;
 let sig_start=12+payload_len+8;
 for index in [24,sig_start,sig_start+3310] {
  let mut bad=decoded.clone();bad[index]^=1;
  let mut z=flate2::write::ZlibEncoder::new(Vec::new(),flate2::Compression::default());z.write_all(&bad)?;
  let mut bytes=b"PQMZIP01".to_vec();bytes.extend((bad.len() as u32).to_be_bytes());bytes.extend(z.finish()?);
  let mut c=card.clone();put(&mut c,0x5f5000,1,&bytes);assert!(restore(&mut c,123456).is_err());
 }
 Ok(())
}
#[test]
fn stale_chunks_equal_generation_conflict_and_no_unchecked_fallback()->Result<()> {
 let (mut card,v)=fixture();put(&mut card,0x5f5000,1,&data(&v,"pure"));put(&mut card,0x5f5100,1,&data(&v,"hybrid"));assert!(restore(&mut card,123456).is_err());
 put(&mut card,0x5f5100,2,&data(&v,"hybrid"));card.objects.get_mut(&0x5f5101).unwrap()[15]=1;
 assert_eq!(restore(&mut card,123456)?.review()["generation"],1);
 Ok(())
}

#[test]
fn legacy_bundle_reports_missing_newer_certificates_without_creating_them()->Result<()> {
 let (mut card,v)=fixture();put(&mut card,0x5f5000,3,&data(&v,"legacy"));
 let restored=restore(&mut card,123456)?;
 assert!(restored.review()["compatibilityFingerprint"].is_null());
 assert_eq!(restored.review()["slots"]["certification"],serde_json::json!(["9c","84"]));
 assert_eq!(restored.review()["publicKeySha256"].as_object().unwrap().len(),6);
 assert_eq!(restored.warnings.len(),4);
 let parent=tempfile::tempdir()?;let out=parent.path().join("old");restored.save(&out)?;
 assert!(!out.join("openpgp-v4-hybrid.asc").exists());assert!(out.join("certificate-bundle.pqkey").is_file());
 Ok(())
}
